<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { message } from 'ant-design-vue'
import { useI18n } from 'vue-i18n'
import { sysuserApi, type SysUser } from '../../api/sysuser'
const { t } = useI18n(); const loading = ref(false); const keyword = ref(''); const status = ref<string | undefined>(); const page = ref(1); const total = ref(0); const rows = ref<SysUser[]>([]); const modal = ref(false); const resetModal = ref(false); const resetTarget = ref<SysUser | null>(null); const newPassword = ref(''); const editing = ref<SysUser | null>(null); const form = ref({ username: '', name: '', password: '', mobile: '', email: '' })
async function load() { loading.value = true; try { const data = await sysuserApi.list({ page: page.value, page_size: 10, keyword: keyword.value || undefined, status: status.value }); rows.value = data.items; total.value = data.total } finally { loading.value = false } }
function open(user?: SysUser) { editing.value = user || null; form.value = user ? { username: user.username, name: user.name, password: '', mobile: '', email: user.email } : { username: '', name: '', password: '', mobile: '', email: '' }; modal.value = true }
async function save() { try { if (editing.value) { const data: Record<string, unknown> = { name: form.value.name, email: form.value.email }; if (form.value.mobile) data.mobile = form.value.mobile; await sysuserApi.update(editing.value.id, data) } else await sysuserApi.create(form.value); modal.value = false; message.success(editing.value ? t('user.updateSuccess') : t('user.createSuccess')); await load() } catch { /* interceptor handles error */ } }
async function disable(user: SysUser) { try { await sysuserApi.disable(user.id); message.success(t('user.disableSuccess')); await load() } catch {} }
async function enable(user: SysUser) { try { await sysuserApi.update(user.id, { status: 1 }); message.success(t('user.updateSuccess')); await load() } catch {} }
async function unlock(user: SysUser) { try { await sysuserApi.unlock(user.id); message.success(t('user.unlockSuccess')); await load() } catch {} }
function openReset(user: SysUser) { resetTarget.value = user; newPassword.value = ''; resetModal.value = true }
async function resetPassword() { if (!resetTarget.value || !newPassword.value) return; try { await sysuserApi.resetPassword(resetTarget.value.id, newPassword.value); resetModal.value = false; message.success(t('user.resetSuccess')) } catch {} }
onMounted(load)
</script>
<template><section class="page-content user-page"><div class="user-toolbar"><a-space><a-input v-model:value="keyword" allow-clear :placeholder="`${t('user.name')} / ${t('user.username')} / ${t('user.mobile')}`" @press-enter="load"/><a-select v-model:value="status" allow-clear style="width:130px"><a-select-option value="1">{{ t('user.active') }}</a-select-option><a-select-option value="2">{{ t('user.disabled') }}</a-select-option><a-select-option value="3">{{ t('user.locked') }}</a-select-option></a-select><a-button :loading="loading" @click="load">{{ t('common.search') }}</a-button><a-button @click="keyword=''; status=undefined; page=1; load()">{{ t('common.reset') }}</a-button></a-space><a-button type="primary" @click="open()">{{ t('user.add') }}</a-button></div><a-table :loading="loading" :data-source="rows" :pagination="{ current: page, pageSize: 10, total }" row-key="id" @change="(p: any) => { page = p.current; load() }"><a-table-column key="name" :title="t('user.name')" data-index="name"/><a-table-column key="username" :title="t('user.username')" data-index="username"/><a-table-column key="mobile" :title="t('user.mobile')" data-index="mobile"/><a-table-column key="email" :title="t('user.email')" data-index="email"/><a-table-column key="status" :title="t('common.status')"><template #default="{ record }"><a-tag :color="record.status === 1 ? 'success' : record.status === 3 ? 'error' : 'warning'">{{ record.status === 1 ? t('user.active') : record.status === 3 ? t('user.locked') : t('user.disabled') }}</a-tag></template></a-table-column><a-table-column key="actions" :title="t('common.operation')"><template #default="{ record }"><a-space><a-button type="link" size="small" @click="open(record)">{{ t('common.edit') }}</a-button><a-button type="link" size="small" @click="openReset(record)">{{ t('user.resetPassword') }}</a-button><a-button v-if="record.status === 3" type="link" size="small" @click="unlock(record)">{{ t('common.unlock') }}</a-button><a-button v-else-if="record.status === 2" type="link" size="small" @click="enable(record)">{{ t('common.enable') }}</a-button><a-button v-else type="link" danger size="small" @click="disable(record)">{{ t('common.disable') }}</a-button></a-space></template></a-table-column></a-table><a-modal v-model:open="modal" :title="editing ? t('common.edit') : t('user.add')" @ok="save"><a-form layout="vertical"><a-form-item :label="t('user.username')"><a-input v-model:value="form.username" :disabled="Boolean(editing)"/></a-form-item><a-form-item :label="t('user.name')"><a-input v-model:value="form.name"/></a-form-item><a-form-item v-if="!editing" :label="t('user.password')"><a-input-password v-model:value="form.password"/></a-form-item><a-form-item :label="t('user.mobile')"><a-input v-model:value="form.mobile" :placeholder="editing ? t('user.mobileKeep') : ''"/></a-form-item><a-form-item :label="t('user.email')"><a-input v-model:value="form.email"/></a-form-item></a-form></a-modal><a-modal v-model:open="resetModal" :title="t('user.resetPassword')" @ok="resetPassword"><a-form layout="vertical"><a-form-item :label="t('user.newPassword')" :help="t('user.passwordHint')"><a-input-password v-model:value="newPassword"/></a-form-item></a-form></a-modal></section></template>
